import { create } from 'zustand';

type CartState = {
  items: Record<string, number>;
  add: (id: string) => void;
  remove: (id: string) => void;
  clear: () => void;
};

export const useCartStore = create<CartState>()((set) => ({
  items: {},
  add: (id) => set((s) => ({ items: { ...s.items, [id]: (s.items[id] ?? 0) + 1 } })),
  remove: (id) =>
    set((s) => {
      const { [id]: _, ...rest } = s.items;
      return { items: rest };
    }),
  clear: () => set({ items: {} }),
}));

// Component: re-renders only when the count changes
const count = useCartStore((s) => Object.keys(s.items).length);
const add = useCartStore((s) => s.add);

import { useShallow } from 'zustand/react/shallow';

// Bad in v5: new object every time -> infinite loop error
// const { items, clear } = useCartStore((s) => ({ items: s.items, clear: s.clear }));

const { items, clear } = useCartStore(
  useShallow((s) => ({ items: s.items, clear: s.clear }))
);

import { atom, useAtom, useAtomValue, useSetAtom } from 'jotai';

const priceAtom = atom(100);
const qtyAtom = atom(2);
const totalAtom = atom((get) => get(priceAtom) * get(qtyAtom)); // derived, read-only

const incrementQtyAtom = atom(null, (get, set) => set(qtyAtom, get(qtyAtom) + 1)); // write-only action

function Total() {
  const total = useAtomValue(totalAtom); // re-renders when price or qty changes
  return <p>{total}</p>;
}

function AddButton() {
  const increment = useSetAtom(incrementQtyAtom); // never re-renders from state changes
  return <button onClick={increment}>+</button>;
}

import { useQuery } from '@tanstack/react-query';

function useTodos(filter: 'all' | 'done') {
  return useQuery({
    queryKey: ['todos', { filter }],
    queryFn: async ({ signal }) => {
      const res = await fetch(`/api/todos?filter=${filter}`, { signal });
      if (!res.ok) throw new Error('Failed to load todos'); // fetch does not reject on HTTP errors
      return (await res.json()) as Todo[];
    },
    staleTime: 30_000,
  });
}

function TodoList() {
  const { data, isPending, isError, error, isFetching } = useTodos('all');
  if (isPending) return <Spinner />;
  if (isError) return <ErrorBox error={error} />;
  return <List todos={data} refreshing={isFetching} />;
}

import { keepPreviousData, useQuery } from '@tanstack/react-query';

function Projects() {
  const [page, setPage] = useState(1);
  const { data, isPlaceholderData } = useQuery({
    queryKey: ['projects', page],
    queryFn: () => fetchProjects(page),
    placeholderData: keepPreviousData,
  });
  return (
    <>
      <ProjectList projects={data?.items ?? []} dimmed={isPlaceholderData} />
      <button disabled={isPlaceholderData || !data?.hasMore} onClick={() => setPage((p) => p + 1)}>Next</button>
    </>
  );
}

