import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';

export const signupSchema = z
  .object({
    email: z.email('Enter a valid email'),
    password: z.string().min(8, 'At least 8 characters'),
    confirm: z.string(),
    age: z.coerce.number().int().min(18, 'You must be 18+'),
  })
  .refine((d) => d.password === d.confirm, { message: 'Passwords do not match', path: ['confirm'] });

type SignupInput = z.input<typeof signupSchema>;
type SignupValues = z.output<typeof signupSchema>;

export function SignupForm() {
  const { register, handleSubmit, setError, formState: { errors, isSubmitting } } = useForm<SignupInput, unknown, SignupValues>({
    resolver: zodResolver(signupSchema),
    defaultValues: { email: '', password: '', confirm: '', age: '' },
    mode: 'onTouched',
  });

  async function onSubmit(values: SignupValues) {
    const res = await signup(values);
    if (res.error === 'EMAIL_TAKEN') setError('email', { message: 'Email already registered' });
  }

  return (
    <form onSubmit={handleSubmit(onSubmit)} noValidate>
      <input {...register('email')} aria-invalid={!!errors.email} />
      {errors.email && <p role="alert">{errors.email.message}</p>}
      <input type="password" {...register('password')} />
      <input type="password" {...register('confirm')} />
      {errors.confirm && <p role="alert">{errors.confirm.message}</p>}
      <input type="number" {...register('age')} />
      <button disabled={isSubmitting}>Sign up</button>
    </form>
  );
}

