const queryClient = useQueryClient();

const addTodo = useMutation({
  mutationFn: (text: string) => api.post<Todo>('/todos', { text }),
  onSuccess: (created) => {
    queryClient.setQueryData(['todos', 'detail', created.id], created);
    return queryClient.invalidateQueries({ queryKey: ['todos', 'list'] }); // awaited: stays pending until lists refetch
  },
});

addTodo.mutate('Write tests');

const toggleTodo = useMutation({
  mutationFn: (todo: Todo) => api.patch(`/todos/${todo.id}`, { done: !todo.done }),
  onMutate: async (todo) => {
    await queryClient.cancelQueries({ queryKey: ['todos', 'list'] });
    const previous = queryClient.getQueryData<Todo[]>(['todos', 'list']);
    queryClient.setQueryData<Todo[]>(['todos', 'list'], (old = []) =>
      old.map((t) => (t.id === todo.id ? { ...t, done: !t.done } : t))
    );
    return { previous };
  },
  onError: (_err, _todo, ctx) => {
    if (ctx?.previous) queryClient.setQueryData(['todos', 'list'], ctx.previous);
    toast.error('Could not update the todo');
  },
  onSettled: () => queryClient.invalidateQueries({ queryKey: ['todos', 'list'] }),
});

const { mutate, isPending, variables, isError } = useMutation({
  mutationFn: (text: string) => api.post('/todos', { text }),
  onSettled: () => queryClient.invalidateQueries({ queryKey: ['todos', 'list'] }),
});

return (
  <ul>
    {todos.map((t) => <li key={t.id}>{t.text}</li>)}
    {isPending && <li className="opacity-50">{variables}</li>}
    {isError && <li className="text-red-600">{variables} <button onClick={() => mutate(variables!)}>Retry</button></li>}
  </ul>
);

